import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import nodemailer from 'nodemailer';
import type { Transporter } from 'nodemailer';

export interface EmailService {
  sendEmail(to: string, subject: string, body: string, html?: boolean): Promise<void>;
  sendTemplateEmail(
    to: string,
    templateName: string,
    context: Record<string, unknown>,
  ): Promise<void>;
  isHealthy(): Promise<boolean>;
}

@Injectable()
export class SmtpEmailService implements EmailService, OnModuleInit {
  private readonly logger = new Logger(SmtpEmailService.name);
  private readonly transporter: Transporter;
  private readonly fromEmail = 'noreply@example.com';
  private readonly fromName = 'Application';

  constructor(private readonly configService: ConfigService) {
    const host = this.configService.getOrThrow<string>('SMTP_HOST');
    const port = parseInt(this.configService.getOrThrow<string>('SMTP_PORT'), 10);
    const secure = this.configService.get<string>('SMTP_SECURE') === 'true';
    const user = this.configService.get<string>('SMTP_USER');
    const pass = this.configService.get<string>('SMTP_PASS');
    this.transporter = nodemailer.createTransport({
      host,
      port,
      secure,
      ...(user !== undefined && user !== ''
        ? { auth: { user, pass: pass ?? '' } }
        : {}),
      pool: true,
      maxConnections: 5,
    });
    this.logger.log('Email client initialized (smtp)');
  }

  async onModuleInit(): Promise<void> {
    const healthy = await this.isHealthy();
    if (!healthy) {
      this.logger.warn('Email service health check failed on init');
    }
  }

  async sendEmail(
    to: string,
    subject: string,
    body: string,
    html = false,
  ): Promise<void> {
    this.logger.log(`Sending email to=${to} subject=${subject}`);
    await this.transporter.sendMail({
      from: `${this.fromName} <${this.fromEmail}>`,
      to,
      subject,
      ...(html ? { html: body } : { text: body }),
    });
    this.logger.log(`Email sent to=${to}`);
  }

  async sendTemplateEmail(
    to: string,
    templateName: string,
    context: Record<string, unknown>,
  ): Promise<void> {
    const body = JSON.stringify(context);
    await this.sendEmail(to, templateName, body, false);
  }

  async isHealthy(): Promise<boolean> {
    try {
      await this.transporter.verify();
      return true;
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(`Email health check failed: ${message}`);
      return false;
    }
  }
}
